--
-- Triggers `devices`
--
DELIMITER $$
CREATE TRIGGER `update_persistent_device` AFTER UPDATE ON `devices` FOR EACH ROW BEGIN
    IF NEW.mac_address IS NOT NULL AND NEW.mac_address != '' AND NEW.mac_address != 'Unknown' THEN
        VALUES (NEW.mac_address, NEW.name, NEW.device_type, NOW(), NOW())
        ON DUPLICATE KEY UPDATE 
            last_seen_at = NOW(),
            total_seen_count = total_seen_count + 1;
    END IF;
END
$$
DELIMITER ;

